function LazyImg({src, alt}) {
  const ref = useRef(null);
  useEffect(()=>{
    const io = new IntersectionObserver(entries => {
      if (entries[0].isIntersecting) {
        ref.current.src = src;
        io.disconnect();
      }
    });
    io.observe(ref.current);
